/bin/bash -lc "python - <<'PY'
import csv, collections
p='inputs/ROSMAP_meta_ad.csv'
with open(p,newline='') as f:
    r=csv.DictReader(f); fields=r.fieldnames; rows=list(r)
groups=collections.defaultdict(list)
for i,row in enumerate(rows, start=2): groups[row['projid']].append((i,row))
print(','.join(['csv_line']+fields))
for k in sorted(groups):
    if len(groups[k])>1:
        for i,row in groups[k]: print(','.join([str(i)]+[row[x] for x in fields]))
PY"

/bin/bash -lc "python - <<'PY'
import csv, collections
p='inputs/ROSMAP_meta_ad.csv'
with open(p,newline='') as f:
    r=csv.DictReader(f); fields=r.fieldnames; rows=list(r)
groups=collections.defaultdict(list)
for i,row in enumerate(rows, start=2): groups[row['projid']].append((i,row))
print(','.join(['csv_line']+fields))
for k in sorted(groups):
    if len(groups[k])>1:
        for i,row in groups[k]: print(','.join([str(i)]+[row[x] for x in fields]))
PY"

